<script setup lang="ts">
import { nextTick, onMounted, ref, watch } from 'vue'
const props = defineProps<{ modelValue: string; readonly?: boolean }>()
const emit = defineEmits<{ 'update:modelValue': [value: string] }>()
const editor = ref<HTMLElement | null>(null)
const sync = () => emit('update:modelValue', editor.value?.innerHTML || '')
const command = async (name: string, value?: string) => { editor.value?.focus(); document.execCommand(name, false, value); sync(); await nextTick() }
const insertLink = () => { const url=window.prompt('Masukkan URL tautan'); if(url) command('createLink',url) }
const insertMedia = (type:'image'|'video') => { const url=window.prompt(`Masukkan URL ${type === 'image' ? 'gambar' : 'video'}`); if(!url) return; const html=type==='image'?`<img src="${url}" alt="" style="max-width:100%;border-radius:12px">`:`<p><a href="${url}" target="_blank" rel="noopener">Tonton video</a></p>`; command('insertHTML',html) }
watch(() => props.modelValue, value => { if(editor.value && editor.value.innerHTML !== value) editor.value.innerHTML=value || '' })
onMounted(() => { if(editor.value) editor.value.innerHTML=props.modelValue || '' })
</script>
<template><div class="overflow-hidden rounded-xl border border-[#D0D5DD] bg-white focus-within:border-[#1B5FD9] focus-within:ring-4 focus-within:ring-[#1B5FD9]/10"><div v-if="!readonly" class="flex flex-wrap gap-1 border-b border-[#E7EBF2] bg-[#F9FAFB] p-2" role="toolbar" aria-label="Pemformatan isi konten"><button type="button" class="tool font-bold" aria-label="Tebal" @click="command('bold')">B</button><button type="button" class="tool italic" aria-label="Miring" @click="command('italic')">I</button><button type="button" class="tool" @click="command('formatBlock','h2')">Judul 2</button><button type="button" class="tool" @click="command('insertUnorderedList')">Daftar</button><button type="button" class="tool" @click="insertLink">Tautan</button><button type="button" class="tool" @click="command('formatBlock','pre')">Kode</button><button type="button" class="tool" @click="insertMedia('image')">Gambar</button><button type="button" class="tool" @click="insertMedia('video')">Video</button><button type="button" class="tool" @click="command('removeFormat')">Hapus format</button></div><div ref="editor" class="prose-editor min-h-[320px] p-4 text-[15px] leading-7 text-[#101828] outline-none" :contenteditable="!readonly" :aria-readonly="readonly" data-placeholder="Tulis isi konten di sini..." @input="sync" /></div></template>
<style scoped>.tool{min-height:40px;border-radius:8px;border:1px solid #e7ebf2;background:#fff;padding:.45rem .7rem;color:#344054;font-size:.75rem;font-weight:700}.tool:hover,.tool:focus-visible{border-color:#1b5fd9;outline:2px solid #d9e7ff}.prose-editor:empty:before{content:attr(data-placeholder);color:#98a2b3}.prose-editor :deep(h2){font-size:1.35rem;font-weight:800;margin:1rem 0 .5rem}.prose-editor :deep(ul){list-style:disc;padding-left:1.5rem}.prose-editor :deep(pre){overflow:auto;border-radius:.75rem;background:#101828;padding:1rem;color:#f8fafc}.prose-editor :deep(a){color:#1b5fd9;text-decoration:underline}</style>
